CREATE EXTENSION IF NOT EXISTS "pg_trgm"; CREATE TABLE IF NOT EXISTS public.drug_interactions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, drug1_rxcui VARCHAR(10) NOT NULL, drug1_name TEXT NOT NULL, drug2_rxcui VARCHAR(10) NOT NULL, drug2_name TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'moderate' CHECK ( severity IN ('contraindicated', 'serious', 'moderate', 'minor') ), description TEXT NOT NULL, clinical_recommendation TEXT, mechanism TEXT, evidence_level TEXT DEFAULT 'established' CHECK ( evidence_level IN ('established', 'probable', 'suspected', 'theoretical') ), excludes_routes TEXT[], excludes_formulations TEXT[], age_ranges JSONB, contraindicated_in_pregnancy BOOLEAN DEFAULT FALSE, contraindicated_in_lactation BOOLEAN DEFAULT FALSE, pregnancy_note TEXT, source TEXT NOT NULL DEFAULT 'local' CHECK ( source IN ('rxnorm', 'local', 'hl7-fhir', 'fda-alert', 'custom-protocol') ), external_id TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE TABLE IF NOT EXISTS public.drug_interaction_cache ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, new_drug_rxcui VARCHAR(10) NOT NULL, new_drug_name TEXT NOT NULL, interactions_found INTEGER DEFAULT 0, severity_max TEXT DEFAULT 'none' CHECK ( severity_max IN ('contraindicated', 'serious', 'moderate', 'minor', 'none') ), details JSONB, checked_at TIMESTAMPTZ DEFAULT now(), expires_at TIMESTAMPTZ DEFAULT (now() + interval '30 days'), checked_by UUID REFERENCES public.profiles(id), created_at TIMESTAMPTZ DEFAULT now() ); CREATE TABLE IF NOT EXISTS public.prescription_dur_reviews ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, prescription_id UUID NOT NULL REFERENCES public.prescriptions(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, reviewed_by UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT, reviewed_at TIMESTAMPTZ DEFAULT now(), status TEXT NOT NULL DEFAULT 'pending' CHECK ( status IN ('pending', 'cleared', 'flagged', 'denied', 'approved_with_conditions') ), ddi_checked BOOLEAN DEFAULT FALSE, ddi_severity TEXT DEFAULT 'none' CHECK ( ddi_severity IN ('contraindicated', 'serious', 'moderate', 'minor', 'none') ), ddi_details JSONB, allergy_checked BOOLEAN DEFAULT FALSE, allergy_conflicts TEXT[], age_checked BOOLEAN DEFAULT FALSE, age_appropriate BOOLEAN, age_note TEXT, pregnancy_checked BOOLEAN DEFAULT FALSE, pregnancy_safe BOOLEAN, pregnancy_note TEXT, renal_checked BOOLEAN DEFAULT FALSE, patient_egfr NUMERIC(6,1), renal_dosage_ok BOOLEAN, renal_note TEXT, hepatic_checked BOOLEAN DEFAULT FALSE, patient_child_pugh_score TEXT, hepatic_dosage_ok BOOLEAN, hepatic_note TEXT, pharmacist_notes TEXT, pharmacist_recommendation TEXT, requires_doctor_approval BOOLEAN DEFAULT FALSE, doctor_approval_status TEXT CHECK ( doctor_approval_status IN ('pending', 'approved', 'denied') ), doctor_approved_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL, doctor_approval_at TIMESTAMPTZ, doctor_approval_note TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_drug_interactions_rxcui_pair ON public.drug_interactions(drug1_rxcui, drug2_rxcui); CREATE INDEX IF NOT EXISTS idx_drug_interactions_hospital ON public.drug_interactions(hospital_id); CREATE INDEX IF NOT EXISTS idx_drug_interactions_reverse ON public.drug_interactions(drug2_rxcui, drug1_rxcui); CREATE INDEX IF NOT EXISTS idx_drug_interaction_cache_patient_drug ON public.drug_interaction_cache(patient_id, new_drug_rxcui); CREATE INDEX IF NOT EXISTS idx_drug_interaction_cache_hospital ON public.drug_interaction_cache(hospital_id); CREATE INDEX IF NOT EXISTS idx_drug_interaction_cache_expires ON public.drug_interaction_cache(expires_at); CREATE INDEX IF NOT EXISTS idx_prescription_dur_reviews_rx_id ON public.prescription_dur_reviews(prescription_id); CREATE INDEX IF NOT EXISTS idx_prescription_dur_reviews_patient ON public.prescription_dur_reviews(patient_id); CREATE INDEX IF NOT EXISTS idx_prescription_dur_reviews_status ON public.prescription_dur_reviews(status); CREATE INDEX IF NOT EXISTS idx_prescription_dur_reviews_hospital ON public.prescription_dur_reviews(hospital_id); CREATE INDEX IF NOT EXISTS idx_prescription_dur_reviews_pending ON public.prescription_dur_reviews(hospital_id, status) WHERE status IN ('pending', 'flagged', 'approved_with_conditions'); ALTER TABLE public.drug_interactions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.drug_interaction_cache ENABLE ROW LEVEL SECURITY; ALTER TABLE public.prescription_dur_reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY drug_interactions_hospital_scope ON public.drug_interactions USING (hospital_id = (SELECT hospital_id FROM public.profiles WHERE id = auth.uid())); CREATE POLICY drug_interaction_cache_hospital_scope ON public.drug_interaction_cache USING (hospital_id = (SELECT hospital_id FROM public.profiles WHERE id = auth.uid())); CREATE POLICY prescription_dur_reviews_hospital_scope ON public.prescription_dur_reviews USING (hospital_id = (SELECT hospital_id FROM public.profiles WHERE id = auth.uid())); GRANT SELECT, INSERT, UPDATE, DELETE ON public.drug_interactions TO authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.drug_interaction_cache TO authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.prescription_dur_reviews TO authenticated; GRANT ALL ON public.drug_interactions TO service_role; GRANT ALL ON public.drug_interaction_cache TO service_role; GRANT ALL ON public.prescription_dur_reviews TO service_role; DROP TRIGGER IF EXISTS drug_interactions_updated_at ON public.drug_interactions; CREATE TRIGGER drug_interactions_updated_at BEFORE UPDATE ON public.drug_interactions FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS drug_interaction_cache_updated_at ON public.drug_interaction_cache; CREATE TRIGGER drug_interaction_cache_updated_at BEFORE UPDATE ON public.drug_interaction_cache FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS prescription_dur_reviews_updated_at ON public.prescription_dur_reviews; CREATE TRIGGER prescription_dur_reviews_updated_at BEFORE UPDATE ON public.prescription_dur_reviews FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS prescription_dur_reviews_audit ON public.prescription_dur_reviews; INSERT INTO public.drug_interactions ( hospital_id, drug1_rxcui, drug1_name, drug2_rxcui, drug2_name, severity, description, clinical_recommendation, mechanism, evidence_level, source ) SELECT h.id, '4324', 'Warfarin', '7052', 'Ibuprofen', 'serious', 'Concurrent use may increase anticoagulant effect and risk of bleeding', 'Avoid NSAIDs with warfarin. Use acetaminophen instead. Monitor INR closely.', 'NSAIDs inhibit platelet function and may displace warfarin from protein binding', 'established', 'rxnorm' FROM public.hospitals h WHERE NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.hospital_id = h.id AND d.drug1_rxcui = '4324' AND d.drug2_rxcui = '7052'); INSERT INTO public.drug_interactions ( hospital_id, drug1_rxcui, drug1_name, drug2_rxcui, drug2_name, severity, description, clinical_recommendation, mechanism, evidence_level, source, age_ranges ) SELECT h.id, '10582', 'Tetracycline', '0', 'Child <8 years', 'contraindicated', 'Tetracyclines cause permanent discoloration of developing teeth', 'Do not use in children <8 years. Use alternative antibiotic class.', 'Tetracyclines form stable complexes with calcium in calcifying teeth', 'established', 'local', jsonb_build_object('min_age_months', 0, 'max_age_months', 96) FROM public.hospitals h WHERE NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.hospital_id = h.id AND d.drug1_rxcui = '10582' AND d.drug2_name = 'Child <8 years'); INSERT INTO public.drug_interactions ( hospital_id, drug1_rxcui, drug1_name, drug2_rxcui, drug2_name, severity, description, clinical_recommendation, mechanism, evidence_level, source ) SELECT h.id, '18827', 'Metformin', '16681', 'Iodinated Contrast', 'serious', 'Risk of contrast-induced nephropathy with metformin continuation', 'Hold metformin 48 hours after contrast administration. Monitor renal function.', 'Contrast may impair renal function; metformin accumulation can cause lactic acidosis', 'established', 'rxnorm' FROM public.hospitals h WHERE NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.hospital_id = h.id AND d.drug1_rxcui = '18827' AND d.drug2_rxcui = '16681'); COMMENT ON TABLE public.drug_interactions IS 'Stores known drug-drug interactions with severity, clinical details, and evidence'; COMMENT ON TABLE public.prescription_dur_reviews IS 'Audit trail of pharmacist medication reviews and doctor approvals. HIPAA compliance required.';